// Contains customizable settings that control app behavior.
extension UIColor {
    convenience init(hex: String) {
        // Remove any characters that aren't hexadecimal digits
        let hexString = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)

        // Default color in case of failure
        var rgbValue: UInt64 = 0

        // Use newer scanner method instead of deprecated scanHexInt32
        if Scanner(string: hexString).scanHexInt64(&rgbValue) {
            // Extract color components
            let r = CGFloat((rgbValue & 0xFF0000) >> 16) / 255.0
            let g = CGFloat((rgbValue & 0x00FF00) >> 8) / 255.0
            let b = CGFloat(rgbValue & 0x0000FF) / 255.0

            // Initialize with extracted values
            self.init(red: r, green: g, blue: b, alpha: 1.0)
        } else {
            // Fallback to a default color
            self.init(red: 0, green: 0, blue: 0, alpha: 1.0)
        }
    }
}

